import{_ as i,c as e,o as a,j as n,Y as o,t as r}from"./chunks/framework.D-NV0Bun.js";const m=JSON.parse('{"title":"docker-container-cp | x-cmd man (docker man1) | Copy files/folders between a container and the","titleTemplate":false,"description":"x-cmd man (docker man1 Manual Page) | docker-container-cp - Copy files/folders between a container and the","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"docker-container-cp | x-cmd man (docker man1) | Copy files/folders between a container and the"}],["meta",{"name":"og:description","content":"x-cmd man (docker man1 Manual Page) | docker-container-cp - Copy files/folders between a container and the"}]]},"headers":[],"params":{"isMan":true,"man":"docker-container-cp","category":"docker man1","desc":"Copy files/folders between a container and the"},"relativePath":"docker/man1/docker-container-cp.md","filePath":"docker/man1/[man].md"}'),l={name:"docker/man1/docker-container-cp.md"},p={class:"visually-hidden"};function h(t,s,c,d,g,k){return a(),e("div",null,[n("h1",p,r(t.$params.man),1),s[0]||(s[0]=o('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>docker-container-cp - Copy files/folders between a container and the local filesystem</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>docker container cp [OPTIONS] CONTAINER:SRC_PATH DEST_PATH|-</strong> docker cp [OPTIONS] SRC_PATH|- CONTAINER:DEST_PATH</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>The <strong>docker container cp</strong> utility copies the contents of <strong>SRC_PATH</strong> to the <strong>DEST_PATH</strong>. You can copy from the container&#39;s file system to the local machine or the reverse, from the local filesystem to the container. If <strong>-</strong> is specified for either the <strong>SRC_PATH</strong> or <strong>DEST_PATH</strong>, you can also stream a tar archive from <strong>STDIN</strong> or to <strong>STDOUT</strong>. The <strong>CONTAINER</strong> can be a running or stopped container. The <strong>SRC_PATH</strong> or <strong>DEST_PATH</strong> can be a file or directory.</p><p>The <strong>docker container cp</strong> command assumes container paths are relative to the container&#39;s <strong>/</strong> (root) directory. This means supplying the initial forward slash is optional; The command sees <strong>compassionate_darwin:/tmp/foo/myfile.txt</strong> and <strong>compassionate_darwin:tmp/foo/myfile.txt</strong> as identical. Local machine paths can be an absolute or relative value. The command interprets a local machine&#39;s relative paths as relative to the current working directory where <strong>docker container cp</strong> is run.</p><p>The <strong>cp</strong> command behaves like the Unix <strong>cp -a</strong> command in that directories are copied recursively with permissions preserved if possible. Ownership is set to the user and primary group at the destination. For example, files copied to a container are created with <strong>UID:GID</strong> of the root user. Files copied to the local machine are created with the <strong>UID:GID</strong> of the user which invoked the <strong>docker container cp</strong> command. If you specify the <strong>-L</strong> option, <strong>docker container cp</strong> follows any symbolic link in the <strong>SRC_PATH</strong>. <strong>docker container cp</strong> does <em>not</em> create parent directories for <strong>DEST_PATH</strong> if they do not exist.</p><p>Assuming a path separator of <strong>/</strong>, a first argument of <strong>SRC_PATH</strong> and second argument of <strong>DEST_PATH</strong>, the behavior is as follows:</p><blockquote><ul><li><p><strong>SRC_PATH</strong> specifies a file</p><ul><li><p><strong>DEST_PATH</strong> does not exist</p><ul><li>the file is saved to a file created at <strong>DEST_PATH</strong></li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- --&gt;</span></span></code></pre></div><ul><li><p><strong>DEST_PATH</strong> does not exist and ends with <strong>/</strong></p><ul><li>Error condition: the destination directory must exist.</li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- --&gt;</span></span></code></pre></div><ul><li><p><strong>DEST_PATH</strong> exists and is a file</p><ul><li>the destination is overwritten with the source file&#39;s contents</li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- --&gt;</span></span></code></pre></div><ul><li><p><strong>DEST_PATH</strong> exists and is a directory</p><ul><li>the file is copied into this directory using the basename from <strong>SRC_PATH</strong></li></ul></li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- --&gt;</span></span></code></pre></div><ul><li><p><strong>SRC_PATH</strong> specifies a directory</p><ul><li><p><strong>DEST_PATH</strong> does not exist</p><ul><li><strong>DEST_PATH</strong> is created as a directory and the <em>contents</em> of the source directory are copied into this directory</li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- --&gt;</span></span></code></pre></div><ul><li><p><strong>DEST_PATH</strong> exists and is a file</p><ul><li>Error condition: cannot copy a directory to a file</li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- --&gt;</span></span></code></pre></div><ul><li><p><strong>DEST_PATH</strong> exists and is a directory</p><ul><li><p><strong>SRC_PATH</strong> does not end with <strong>/.</strong> (that is: <em>slash</em> followed by <em>dot</em>)</p><ul><li>the source directory is copied into this directory</li></ul></li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;!-- --&gt;</span></span></code></pre></div><ul><li><p><strong>SRC_PATH</strong> does end with <strong>/.</strong> (that is: <em>slash</em> followed by <em>dot</em>)</p><ul><li>the <em>content</em> of the source directory is copied into this directory</li></ul></li></ul></li></ul></li></ul></blockquote><p>The command requires <strong>SRC_PATH</strong> and <strong>DEST_PATH</strong> to exist according to the above rules. If <strong>SRC_PATH</strong> is local and is a symbolic link, the symbolic link, not the target, is copied by default. To copy the link target and not the link, specify the <strong>-L</strong> option.</p><p>A colon (<strong>:</strong>) is used as a delimiter between <strong>CONTAINER</strong> and its path. You can also use <strong>:</strong> when specifying paths to a <strong>SRC_PATH</strong> or <strong>DEST_PATH</strong> on a local machine, for example <strong>file:name.txt</strong>. If you use a <strong>:</strong> in a local machine path, you must be explicit with a relative or absolute path, for example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/path/to/file:name.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> or</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> `</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./file:name.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">`</span></span></code></pre></div><p>It is not possible to copy certain system files such as resources under <strong>/proc</strong>, <strong>/sys</strong>, <strong>/dev</strong>, tmpfs, and mounts created by the user in the container. However, you can still copy such files by manually running <strong>tar</strong> in <strong>docker exec</strong>. For example (consider <strong>SRC_PATH</strong> and <strong>DEST_PATH</strong> are directories):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ccf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dirname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SRC_PATH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">basename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SRC_PATH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Cxf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DEST_PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span></code></pre></div><p>or</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Ccf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dirname</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SRC_PATH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">basename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SRC_PATH</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> foo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Cxf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DEST_PATH</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span></span></code></pre></div><p>Using <strong>-</strong> as the <strong>SRC_PATH</strong> streams the contents of <strong>STDIN</strong> as a tar archive. The command extracts the content of the tar to the <strong>DEST_PATH</strong> in container&#39;s filesystem. In this case, <strong>DEST_PATH</strong> must specify a directory. Using <strong>-</strong> as the <strong>DEST_PATH</strong> streams the contents of the resource as a tar archive to <strong>STDOUT</strong>.</p><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><p>Suppose a container has finished producing some output as a file it saves to somewhere in its filesystem. This could be the output of a build job or some other computation. You can copy these outputs from the container to a location on your local host.</p><p>If you want to copy the <strong>/tmp/foo</strong> directory from a container to the existing <strong>/tmp</strong> directory on your host. If you run <strong>docker container cp</strong> in your <strong>~</strong> (home) directory on the local host:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compassionate_darwin:tmp/foo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp</span></span></code></pre></div><p>Docker creates a <strong>/tmp/foo</strong> directory on your host. Alternatively, you can omit the leading slash in the command. If you execute this command from your home directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compassionate_darwin:tmp/foo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tmp</span></span></code></pre></div><p>If <strong>~/tmp</strong> does not exist, Docker will create it and copy the contents of <strong>/tmp/foo</strong> from the container into this new directory. If <strong>~/tmp</strong> already exists as a directory, then Docker will copy the contents of <strong>/tmp/foo</strong> from the container into a directory at <strong>~/tmp/foo</strong>.</p><p>When copying a single file to an existing <strong>LOCALPATH</strong>, the <strong>docker container cp</strong> command will either overwrite the contents of <strong>LOCALPATH</strong> if it is a file or place it into <strong>LOCALPATH</strong> if it is a directory, overwriting an existing file of the same name if one exists. For example, this command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sharp_ptolemy:/tmp/foo/myfile.txt</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /test</span></span></code></pre></div><p>If <strong>/test</strong> does not exist on the local machine, it will be created as a file with the contents of <strong>/tmp/foo/myfile.txt</strong> from the container. If <strong>/test</strong> exists as a file, it will be overwritten. Lastly, if <strong>/test</strong> exists as a directory, the file will be copied to <strong>/test/myfile.txt</strong>.</p><p>Next, suppose you want to copy a file or folder into a container. For example, this could be a configuration file or some other input to a long running computation that you would like to place into a created container before it starts. This is useful because it does not require the configuration file or other input to exist in the container image.</p><p>If you have a file, <strong>config.yml</strong>, in the current directory on your local host and wish to copy it to an existing directory at <strong>/etc/my-app.d</strong> in a container, this command can be used:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config.yml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myappcontainer:/etc/my-app.d</span></span></code></pre></div><p>If you have several files in a local directory <strong>/config</strong> which you need to copy to a directory <strong>/etc/my-app.d</strong> in a container:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /config/.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myappcontainer:/etc/my-app.d</span></span></code></pre></div><p>The above command will copy the contents of the local <strong>/config</strong> directory into the directory <strong>/etc/my-app.d</strong> in the container.</p><p>Finally, if you want to copy a symbolic link into a container, you typically want to copy the linked target and not the link itself. To copy the target, use the <strong>-L</strong> option, for example:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ln</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/somefile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/somefile.ln</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> container</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /tmp/somefile.ln</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> myappcontainer:/tmp/</span></span></code></pre></div><p>This command copies content of the local <strong>/tmp/somefile</strong> into the file <strong>/tmp/somefile.ln</strong> in the container. Without <strong>-L</strong> option, the <strong>/tmp/somefile.ln</strong> preserves its symbolic link but not its content.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p><strong>-a</strong>, <strong>--archive</strong>[=false] Archive mode (copy all uid/gid information)</p><p><strong>-L</strong>, <strong>--follow-link</strong>[=false] Always follow symbol link in SRC_PATH</p><p><strong>-h</strong>, <strong>--help</strong>[=false] help for cp</p><p><strong>-q</strong>, <strong>--quiet</strong>[=false] Suppress progress output during copy. Progress output is automatically suppressed if no terminal is attached</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>docker-container(1)</strong></p>',44))])}const u=i(l,[["render",h]]);export{m as __pageData,u as default};
